 const rows=(snapshot.checks||[]).map(c=>{const row=document.createElement('div');row.className=`field-check${!c.present||c.consistent===false?' missing':''}${c.severity?` risk-${c.severity}`:''}`;const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.checkId=c.id;input.checked=c.confirmed;input.disabled=snapshot.busy||Boolean(snapshot.proposal);label.append(input,textElement('strong',c.kind==='consistency'?consistencyLabel(c):c.label));const source=c.kind==='manual'?(c.id==='completeness'?inspectorCopy('{count} Ausgangsdatei(en)',{count:inspectResult?.previews.length||0}):inspectorCopy(c.source)):c.source,translated=c.kind==='manual'?inspectorCopy(c.translated):c.translated;const values=textElement('small',`${source} → ${translated}`);values.dataset.noTranslate='';row.append(label,values);if(c.issue)row.append(textElement('small',c.kind==='consistency'?consistencyIssue(c):inspectorCopy(c.issue)));if(!['manual','consistency'].includes(c.kind)){const b=textElement('button','Originalstelle ansehen','text-button question-action question-source');b.onclick=()=>focusField(c);row.append(b);}return row;});$('#inspect-checks').replaceChildren(...rows);$('#check-count').dataset.noTranslate='';$('#check-count').textContent=inspectorCopy('{confirmed} / {total} geprüft',{confirmed:(snapshot.checks||[]).filter(c=>c.confirmed).length,total:(snapshot.checks||[]).length});$('#save-checks').disabled=snapshot.busy||Boolean(snapshot.proposal);
